"""Triple Massey products and the weight-excess certificate."""

from __future__ import annotations

from fractions import Fraction
from typing import Callable, Dict, List, Optional, Sequence, Tuple

Element = Dict[str, Fraction]
Vector = List[Fraction]
Matrix = List[Vector]


def row_reduce(rows: Matrix) -> Matrix:
    mat: Matrix = [list(r) for r in rows]
    if not mat:
        return mat
    ncols = len(mat[0])
    pivot_row = 0
    for col in range(ncols):
        pivot = next((r for r in range(pivot_row, len(mat)) if mat[r][col] != 0), None)
        if pivot is None:
            continue
        mat[pivot_row], mat[pivot] = mat[pivot], mat[pivot_row]
        inv = Fraction(1, 1) / mat[pivot_row][col]
        mat[pivot_row] = [inv * v for v in mat[pivot_row]]
        for r in range(len(mat)):
            if r != pivot_row and mat[r][col] != 0:
                f = mat[r][col]
                mat[r] = [a - f * b for a, b in zip(mat[r], mat[pivot_row])]
        pivot_row += 1
        if pivot_row == len(mat):
            break
    return [r for r in mat if any(v != 0 for v in r)]


def rank(rows: Matrix) -> int:
    return len(row_reduce(rows))


def in_span(vectors: Matrix, target: Vector) -> bool:
    if all(v == 0 for v in target):
        return True
    return rank(list(vectors) + [list(target)]) == rank(vectors)


def solve(columns: Matrix, target: Vector) -> Optional[Vector]:
    """Solve sum_j c_j columns[j] = target exactly, or report inconsistency."""
    if not columns:
        return [] if all(v == 0 for v in target) else None
    nrows = len(target)
    aug = [[columns[j][i] for j in range(len(columns))] + [target[i]] for i in range(nrows)]
    red = row_reduce(aug)
    ncols = len(columns)
    coeffs: Vector = [Fraction(0)] * ncols
    for row in red:
        pivot = next((j for j in range(ncols + 1) if row[j] != 0), None)
        if pivot is None:
            continue
        if pivot == ncols:
            return None
        coeffs[pivot] = row[ncols]
    check = [Fraction(0)] * nrows
    for j, c in enumerate(coeffs):
        if c:
            for i in range(nrows):
                check[i] += c * columns[j][i]
    return coeffs if check == list(target) else None


def massey_triple(
    basis: Sequence[str],
    bideg: Dict[str, Tuple[int, int]],
    mul: Callable[[Element, Element], Element],
    d: Callable[[Element], Element],
    x: Element,
    y: Element,
    z: Element,
    alpha: int = 1,
) -> Dict[str, object]:
    """Compute <x, y, z>, decide whether it contains 0, and report the excess.

    Steps: solve d u = x y and d v = y z; form m = (-1)^{deg x} u z - x v; check
    that m is a cocycle; test m against the coboundaries together with the
    indeterminacy subspace spanned by { c z } and { x c' } for cocycles c, c'.
    The weight excess of m is  weight(m) - alpha * degree(m); by the vanishing
    theorem, a nonzero excess forces exactness under purity, and conversely a
    nonzero class certifies that no pure weight grading exists.
    """
    index = {b: i for i, b in enumerate(basis)}

    def vec(e: Element) -> Vector:
        v: Vector = [Fraction(0)] * len(basis)
        for k, c in e.items():
            v[index[k]] = c
        return v

    def bidegree(e: Element) -> Optional[Tuple[int, int]]:
        s = {bideg[k] for k in e}
        return s.pop() if len(s) == 1 else None

    cols = [vec(d({b: Fraction(1)})) for b in basis]
    u_coeffs = solve(cols, vec(mul(x, y)))
    v_coeffs = solve(cols, vec(mul(y, z)))
    if u_coeffs is None or v_coeffs is None:
        return {"defined": False}
    u = {b: c for b, c in zip(basis, u_coeffs) if c}
    v = {b: c for b, c in zip(basis, v_coeffs) if c}

    p = bidegree(x)
    assert p is not None, "x must be bihomogeneous"
    sign = Fraction(-1) ** p[0]
    left = {k: sign * c for k, c in mul(u, z).items()}
    right = mul(x, v)
    m: Element = dict(left)
    for k, c in right.items():
        m[k] = m.get(k, Fraction(0)) - c
        if m[k] == 0:
            del m[k]

    bm = bidegree(m)
    excess = None if bm is None else bm[1] - alpha * bm[0]
    boundaries = cols
    return {
        "defined": True,
        "u": u,
        "v": v,
        "representative": m,
        "bidegree": bm,
        "weight_excess": excess,
        "is_cocycle": d(m) == {},
        "exact_for_this_choice": in_span(boundaries, vec(m)),
    }

